window.AUTH=window.AUTH||{};window.AUTH["18-481"]={"d":"18-481","id":"2018/18-481","n":"Food Marketing Institute v. Argus Leader Media","briefs":[{"k":"petitioner","label":"Brief of petitioner Food Marketing Institute","date":"2019-02-15","url":"https://www.supremecourt.gov/DocketPDF/18/18-481/88748/20190215204958915_1.%20Brief%20on%20the%20Merits.pdf","side":"pet","n":78},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-02-22","url":"https://www.supremecourt.gov/DocketPDF/18/18-481/89322/20190222154506474_18-481tsacUnitedStates.pdf","side":"us","n":75},{"k":"respondent","label":"Brief of respondent Argus Leader Media, d/b/a Argus Leader","date":"2019-03-18","url":"https://www.supremecourt.gov/DocketPDF/18/18-481/92325/20190318174331610_190309%20Brief%20for%20E-Filing.pdf","side":"res","n":123},{"k":"reply","label":"Reply of petitioner Food Marketing Institute","date":"2019-04-05","url":"https://www.supremecourt.gov/DocketPDF/18/18-481/95524/20190405142634575_Reply%20for%20Petitioner.pdf","side":"pet","n":43}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-481_5426.pdf","tr":true,"items":[{"t":"case","label":"9 to 5 Organization for Women Office Workers v. Board of Governors of the Federal Reserve System","cite":"721 F.2d 1","y":1983,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/721/1/","by":{"0":"38","2":"25, 51"}},{"t":"case","label":"Anderson v. Department of Health and Human Services","cite":"907 F.2d 936","y":1990,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/907/936/","by":{"0":"38","2":"25"}},{"t":"case","label":"Baldrige v. Shapiro","cite":"455 U.S. 345","y":1982,"id":"1981/80-1436","sc":1,"sum":"These cases present the question whether lists of addresses collected and utilized by the Bureau of the Census are exempt from disclosure, either by way of civil discovery or the Freedom of Information Act (FOIA), under the confidentiality provisions of the Census Act, 13 U. S. C. §§ 8 and 9. Section 8(b) allows the Secretary of Commerce to reveal statistical materials \"which do not disclose the information reported …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Brooke Group Ltd. v. Brown & Williamson Tobacco Corp.","cite":"509 U.S. 209","y":1993,"id":"1992/92-466","sc":1,"sum":"Brown & Williamson is entitled to judgment as a matter of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Burnet v. Coronado Oil & Gas Co.","cite":"285 U.S. 393","y":1932,"id":"scdb/1931-095","sc":1,"sum":"(1) The lease was an instrumentality of the State in the exercise of a strictly governmental function. P. 398. (2) Application of the federal income tax to the income derived from the lease by the lessee was therefore unconstitutional. Gillespie v. Oklahoma, 257 U. S.501, followed; Group No. 1 Oil Corp. v. Bass, 283 U. S.279, distinguished. Id. 60 App. D. C. 233; 50 F. (2d) 998, affirmed. CERTIORARI, 284 U. S. 606, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Center for Public Integrity v. U.S. Department of Energy","cite":"287 F. Supp. 3d 50","y":2018,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/287/50/","by":{"0":"44"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"37","2":"38"}},{"t":"case","label":"CNA Financial Corp. v. Donovan","cite":"830 F.2d 1132","url":"https://www.courtlistener.com/c/F.2d/830/1132/","by":{"0":"39"}},{"t":"case","label":"Continental Oil Co. v. Federal Power Commission","cite":"519 F.2d 31","y":1975,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/519/31/","by":{"0":"38"}},{"t":"case","label":"Continental Stock Transfer & Trust Co. v. SEC","cite":"566 F.2d 373","y":1977,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/566/373/","by":{"0":"38","2":"24"}},{"t":"case","label":"(vi) Critical Mass Energy Project v. Nuclear Regulatory Commission","cite":"931 F.2d 939","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/931/939/","op":1,"by":{"0":"28"}},{"t":"case","label":"Critical Mass Energy Project v. Nuclear Regulatory Commission","cite":"975 F.2d 971","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/975/971/","by":{"0":"29, 30, 37, 38, 39, 41"}},{"t":"case","label":"Crooker v. Bureau of Alcohol, Tobacco and Firearms","cite":"670 F.2d 1051","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/670/1051/","by":{"0":"37"}},{"t":"case","label":"Department of the Interior v. Klamath Water Users Protective Association","cite":"532 U.S. 1","y":2001,"id":"2000/99-1871","sc":1,"sum":"The Court that there is no exemption under FOIA for the correspondence between the Tribes and the Bureau. Because the Klamath Tribe advocated its own positions in the water allocation proceedings, the communications between it and the Bureau did not equate to the role that personnel fulfils, in that personnel do not represent their own interests.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"op":2,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"EPA v. Mink","cite":"410 U.S. 73","y":1973,"id":"1972/71-909","sc":1,"op":2,"sum":"Respondent Members of Congress brought suit under the Freedom of Information Act of 1966 to compel disclosure of nine documents that various officials had prepared for the President concerning a scheduled underground nuclear test. All but three were classified as Top Secret or Secret under E. 0. 10501, and petitioners represented that all were inter-agency or intra-agency documents used in the Executive Branch's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 43","2":"40, 60"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Services, Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"0":"27","2":"51"}},{"t":"case","label":"FBI v. Abramson","cite":"456 U.S. 615","y":1982,"id":"1981/80-1735","sc":1,"op":2,"sum":"Noting our “oftrepeated caveat that FOIA exemptions are to be narrowly construed”.","sumSrc":"opinion","by":{"0":"32","1":"21","2":"60"}},{"t":"case","label":"FCC v. AT&T, Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"op":3,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"0":"21","2":"45"}},{"t":"case","label":"GC Micro Corp. v. Defense Logistics Agency","cite":"33 F.3d 1109","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/33/1109/","by":{"0":"49","2":"63"}},{"t":"case","label":"General Electric Co. v. U.S. Nuclear Regulatory Commission","cite":"750 F.2d 1394","y":1984,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/750/1394/","by":{"0":"38","2":"16, 25"}},{"t":"case","label":"General Services Administration v. Benson","cite":"415 F.2d 878","y":1969,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/415/878/","op":1,"by":{"0":"21"}},{"t":"case","label":"Gray v. Netherland","cite":"518 U.S. 152","y":1996,"id":"1995/95-6510","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court ruled that the notice-of-evidence claim would require the adoption of a new constitutional rule and therefore could not be raised in a habeas petition.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Greenberg v. FDA","cite":"775 F.2d 1169","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/775/1169/","by":{"0":"42"}},{"t":"case","label":"Greenberg v. FDA","cite":"803 F.2d 1213","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/803/1213/","by":{"0":"42"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"31","3":"19"}},{"t":"case","label":"Kelly v. Robinson","cite":"479 U.S. 36","y":1986,"id":"1986/85-1033","sc":1,"op":1,"sum":"Section 523(a)(7) preserves from discharge in Chapter 7 any condition a state criminal court imposes as part of a criminal sentence. Thus, restitution obligations, imposed as conditions of probation in state criminal proceedings, are not dischargeable.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Madel v. U.S. Department of Justice","cite":"784 F.3d 448","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/784/448/","by":{"0":"38"}},{"t":"case","label":"McDonnell Douglas Corp. v. NASA","cite":"180 F.3d 303","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/180/303/","by":{"0":"49"}},{"t":"case","label":"McDonnell Douglas Corp. v. U.S. Department of the Air Force","cite":"375 F.3d 1182","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/375/1182/","by":{"0":"49","2":"63","3":"19"}},{"t":"case","label":"McDonnell Douglass Corp. v. U.S. EEOC","cite":"922 F. Supp. 235","y":1996,"court":"E.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp./922/235/","by":{"0":"44"}},{"t":"case","label":"Milner v. Department of the Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"op":5,"ar":8,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"0":"17, 21, 32, 37","1":"21, 22","2":"25"}},{"t":"case","label":"Nadler v. FDIC","cite":"92 F.3d 93","y":1996,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/92/93/","by":{"0":"50"}},{"t":"case","label":"National Archives and Records Administration v. Favish","cite":"541 U.S. 157","y":2005,"id":"2003/02-954","sc":1,"sum":"The Court held that the Foster family's interest in privacy outweighed the public interest in seeing pictures from Vincent Foster's death scene. The public interest could only trump privacy interests if Favish could present evidence that the government might have acted improperly. Favish failed to do so.","sumSrc":"Oyez","by":{"0":"32","2":"32, 33, 53","3":"10, 18"}},{"t":"case","label":"National Parks & Conservation Association v. Morton","cite":"498 F.2d 765","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/498/765/","op":18,"ar":10,"by":{"0":"passim","1":"7, 11, 18, 19","2":"24, 36","3":"passim"}},{"t":"case","label":"New Hampshire Right to Life v. Department of Health and Human Services","cite":"136 S. Ct. 383","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./136/383/","sc":1,"sum":"Describing the Court’s repeated practice of “reject[ing] interpretations of * * * FOIA exemptions that diverge from the text”.","sumSrc":"brief:0","by":{"0":"17, 30, 41, 43, 49, 50","1":"24","3":"22"}},{"t":"case","label":"New Hampshire Right to Life v. Department of Health and Human Services","cite":"778 F.3d 43","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/778/43/","sum":"Rejecting a “myopic” view of competition.","sumSrc":"brief:0","by":{"0":"49"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 33, 39","3":"9"}},{"t":"case","label":"NLRB v. Sears, Roebuck & Co.","cite":"421 U.S. 132","y":1975,"id":"1974/73-1233","sc":1,"sum":"Under the procedure for adjudicating unfair labor practice cases under the National Labor Relations Act, if a National Labor Relations Board (NLRB) Regional Director, with whom unfair labor practice charges are filed in the first instance and to whom the NLRB's General Counsel has delegated the initial power to decide whether or not to issue a complaint, believes that the charge has no merit, the charging party has …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 27"}},{"t":"case","label":"OSHA Data/CIH, Inc. v. U.S. Department of Labor","cite":"220 F.3d 153","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/220/153/","by":{"0":"38","2":"25"}},{"t":"case","label":"Pac. Architects & Eng’rs Inc. v. U.S. Dep’t of State","cite":"906 F.2d 1345","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/906/1345/","by":{"0":"38","2":"25"}},{"t":"case","label":"People for the Ethical Treatment of Animals v. U.S. Department of Health and Human Services","cite":"901 F.3d 343","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/901/343/","by":{"0":"49"}},{"t":"case","label":"Pereira v. United States","cite":"347 U.S. 1","y":1954,"id":"scdb/1953-034","sc":1,"sum":"The convictions are affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Public Citizen Health Research Group v. FDA","cite":"704 F.2d 1280","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/704/1280/","op":1,"by":{"0":"48, 50","2":"32, 56"}},{"t":"case","label":"Puerto Rico v. Franklin California Tax-Free Trust","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"op":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Renegotiation Board v. Grumann Aircraft Engineering Corp.","cite":"421 U.S. 168","y":1975,"id":"1974/73-1316","sc":1,"sum":"Neither the Regional Board nor Division Reports are final opinions and they do fall within Exemption 5, since (1) only the full Board has the power by law to make the decision whether excessive profits exist; (2) both types of reports are prepared prior to that decision and are used by the Board in its deliberations; and (3) the evidence fails to support the conclusion that the reasoning in the reports is adopted by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"State of Utah v. U.S. Department of the Interior","cite":"256 F.3d 967","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/256/967/","by":{"0":"49"}},{"t":"case","label":"Sterling Drug, Inc. v. FTC","cite":"450 F.2d 698","y":1971,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/450/698/","op":1,"by":{"0":"21, 30, 30","1":"18"}},{"t":"case","label":"Sullivan v. Finkelstein","cite":"110 S. Ct. 2658","y":1990,"id":"1989/89-504","sc":1,"sum":"The Secretary may immediately appeal a district court order effectively invalidating regulations limiting the kinds of inquiries that must be made to determine entitlement to disability insurance benefits and remanding a claim to the Secretary for consideration without those restrictions. Pp. 623-631. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"U.S. Department of Defense v. Federal Labor Relations Authority","cite":"510 U.S. 487","y":1994,"id":"1993/92-1223","sc":1,"sum":"The Privacy Act forbids the disclosure of employee addresses to collective-bargaining representatives pursuant to requests made under the Labor Statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 33, 35","1":"16, 26"}},{"t":"case","label":"U.S. Department of Justice v. Landano","cite":"508 U.S. 165","y":1993,"id":"1992/91-2054","sc":1,"op":2,"sum":"Respondent Landano was convicted in New Jersey state court for murdering a police officer during what may have been a gang-related robbery. In an effort to support his claim in subsequent state-court proceedings that the prosecution violated Brady v. Maryland,373 U. S. 83, by withholding material exculpatory evidence, he filed Freedom of Information Act (FOIA) requests with the Federal Bureau of Investigation …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 19, 20","1":"13, 14, 17, 24","2":"26, 27, 43, 44, 45","3":"13, 14"}},{"t":"case","label":"U.S. Department of Justice v. Reporters Committee for Freedom of the Press","cite":"489 U.S. 749","y":1982,"id":"1988/87-1379","sc":1,"sum":"The Court held that an individual's interest in nondisclosure of any criminal records that the FBI might have on him or her is precisely the sort of \"personal privacy\" that Congress intended to protect when it enacted FOIA exemptions. Balancing public knowledge interests against privacy considerations, the Court explained that RCFP's request was overly broad.","sumSrc":"Oyez","by":{"0":"35","1":"1, 10, 11, 16, 24","2":"33"}},{"t":"case","label":"U.S. Department of Justice v. Tax Analysts","cite":"492 U.S. 136","y":1989,"id":"1988/88-782","sc":1,"sum":"The FOIA requires the Department to make available copies of district court decisions it receives in the course of litigating tax cases.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"22"}},{"t":"case","label":"U.S. Department of State v. Washington Post Co.","cite":"456 U.S. 595","y":1982,"id":"1981/81-535","sc":1,"sum":"The citizenship information sought by respondent satisfies the \"similar files\" requirement of Exemption 6, and hence the State Department's denial of the request should have been sustained upon a showing that release of the information would constitute a clearly unwarranted invasion of personal privacy. Although Exemption 6's language sheds little light on what Congress meant by \"similar files,\" the legislative …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"xi United States v. Mississippi Valley Generating Co.","cite":"364 U.S. 520","y":1961,"id":"1960/26","sc":1,"sum":"The consultant violated 18 U. S. C. § 434, and public policy forbids enforcement of the contract.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","2":"27"}},{"t":"case","label":"United States v. Weber Aircraft Corp.","cite":"465 U.S. 792","y":1984,"id":"1983/82-1616","sc":1,"op":2,"sum":"The statements in question are protected from disclosure by Exemption 5. The Exemption's plain language, as construed by this Court's prior decisions, is sufficient to resolve the question presented. The statements are unquestionably \"intra-agency memorandums or letters\" within the meaning of the Exemption, and, since the Machin privilege normally protects them from civil discovery, they \"would not be available by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 26, 27, 32"}},{"t":"case","label":"Volvo Trucks North America, Inc. v. ReederSimco GMC, Inc.","cite":"546 U.S. 164","y":2006,"id":"2005/04-905","sc":1,"sum":"The Court ruled that for a manufacturer to be liable under the RPA, dealers must be in actual competition with each other.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Westinghouse Electric Corp. v. Schlesinger","cite":"542 F.2d 1190","y":1976,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/542/1190/","by":{"0":"38"}},{"t":"case","label":"Wisconsin Central Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Worthington Compressors, Inc. v. Costle","cite":"662 F.2d 45","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/662/45/","by":{"0":"50"}},{"t":"usc","label":"2 U.S.C. § 603","url":"https://www.law.cornell.edu/uscode/text/2/603","by":{"0":"36"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","subs":["(a)(8)","(b)","(b)(3)","(b)(4)","(b)(7)(D)","(a)(3)(A)","(a)(4)(B)","(b)(2)","(a)","(a)(4)(A)(vii)","(a)(8)(A)(i)","(b)(3)(B)","(e)(1)(A)","(e)(6)(A)","(a)(6)","(b)(5)","(b)(6)"],"stext":{"head":"§552. Public information; agency rules, opinions, orders, records, and proceedings","paras":[[0,"(a) Each agency shall make available to the public information as follows:"],[0,"(1) Each agency shall separately state and currently publish in the Federal Register for the guidance of the public—"],[1,"(A) descriptions of its central and field organization and the established places at which, the employees (and in the case of a uniformed service, the members) from whom, and the methods whereby, the public may obtain information, make submittals or requests, or obtain decisions;"],[1,"(B) statements of the general course and method by which its functions are channeled and determined, including the nature and requirements of all formal and informal procedures available;"],[1,"(C) rules of procedure, descriptions of forms available or the places at which forms may be obtained, and instructions as to the scope and contents of all papers, reports, or examinations;"],[1,"(D) substantive rules of general applicability adopted as authorized by law, and statements of general policy or interpretations of general applicability formulated and adopted by the agency; and"],[1,"(E) each amendment, revision, or repeal of the foregoing."],[0,"Except to the extent that a person has actual and timely notice of the terms thereof, a person may not in any manner be required to resort to, or be adversely affected by, a matter required to be published in the Federal Register and not so published. For the purpose of this paragraph, matter reasonably available to the class of persons affected thereby is deemed published in the Federal Register when incorporated by reference therein with the approval of the Director of the Federal Register."],[0,"(2) Each agency, in accordance with published rules, shall make available for public inspection in an electronic format—"],[1,"(A) final opinions, including concurring and dissenting opinions, as well as orders, made in the adjudication of cases;"],[1,"(B) those statements of policy and interpretations which have been adopted by the agency and are not published in the Federal Register;"],[1,"(C) administrative staff manuals and instructions to staff that affect a member of the public;"],[1,"(D) copies of all records, regardless of form or format—"],[2,"(i) that have been released to any person under paragraph (3); and"],[2,"(ii)(I) that because of the nature of their subject matter, the agency determines have become or are likely to become the subject of subsequent requests for substantially the same records; or"],[2,"(II) that have been requested 3 or more times; and"],[1,"(E) a general index of the records referred to under subparagraph (D);"],[0,"unless the materials are promptly published and copies offered for sale. For records created on or after November 1, 1996, within one year after such date, each agency shall make such records available, including by computer telecommunications or, if computer telecommunications means have not been established by the agency, by other electronic means. To the extent required to prevent a clearly unwarranted invasion of personal privacy, an agency may delete identifying details when it makes available or publishes an opinion, statement of policy, interpretation, staff manual, instruction, or copies of records referred to in subparagraph (D). However, in each case the justification for the deletion shall be explained fully in writing, and the extent of such deletion shall be indicated on the portion of the record which is made available or published, unless including that indication would harm an interest protected by the exemption in subsection (b) under which the deletion is made. If technically feasible, the extent of the deletion shall be indicated at the place in the record where the deletion was made. Each agency shall also maintain and make available for public inspection in an electronic format current indexes providing identifying information for the public as to any matter issued, adopted, or promulgated after July 4, 1967, and required by this paragraph to be made available or published. Each agency shall promptly publish, quarterly or more frequently, and distribute (by sale or otherwise) copies of each index or supplements thereto unless it determines by order published in the Federal Register that the publication would be unnecessary and impracticable, in which case the agency shall nonetheless provide copies of such index on request at a cost not to exceed the direct cost of duplication. Each agency shall make the index referred to in subparagraph (E) available by computer telecommunications by December 31, 1999. A final order, opinion, statement of policy, interpretation, or staff manual or instruction that affects a member of the public may be relied on, used, or cited as precedent by an agency against a party other than an agency only if—"],[1,"(i) it has been indexed and either made available or published as provided by this paragraph; or"],[1,"(ii) the party has actual and timely notice of the terms thereof."],[0,"(3)(A) Except with respect to the records made available under paragraphs (1) and (2) of this subsection, and except as provided in subparagraph (E), each agency, upon any request for records which (i) reasonably describes such records and (ii) is made in accordance with published rules stating the time, place, fees (if any), and procedures to be followed, shall make the records promptly available to any person."],[0,"(B) In making any record available to a person under this paragraph, an agency shall provide the record in any form or format requested by the person if the record is readily reproducible by the agency in that form or format. Each agency shall make reasonable efforts to maintain its records in forms or formats that are reproducible for purposes of this section."],[0,"(C) In responding under this paragraph to a request for records, an agency shall make reasonable efforts to search for the records in electronic form or format, except when such efforts would significantly interfere with the operation of the agency's automated information system."],[0,"(D) For purposes of this paragraph, the term \"search\" means to review, manually or by automated means, agency records for the purpose of locating those records which are responsive to a request."],[0,"(E) An agency, or part of an agency, that is an element of the intelligence community (as that term is defined in section 3(4) of the National Security Act of 1947 (50 U.S.C. 401a(4))) 1 shall not make any record available under this paragraph to—"],[1,"(i) any government entity, other than a State, territory, commonwealth, or district of the United States, or any subdivision thereof; or"],[1,"(ii) a representative of a government entity described in clause (i)."],[0,"(4)(A)(i) In order to carry out the provisions of this section, each agency shall promulgate regulations, pursuant to notice and receipt of public comment, specifying the schedule of fees applicable to the processing of requests under this section and establishing procedures and guidelines for determining when such fees should be waived or reduced. Such schedule shall conform to the guidelines which shall be promulgated, pursuant to notice and receipt of public comment, by the Director of the Office of Management and Budget and which shall provide for a uniform schedule of fees for all agencies."],[0,"(ii) Such agency regulations shall provide that—"],[1,"(I) fees shall be limited to reasonable standard charges for document search, duplication, and review, when records are requested for commercial use;"],[1,"(II) fees shall be limited to reasonable standard charges for document duplication when records are not sought for commercial use and the request is made by an educational or noncommercial scientific institution, whose purpose is scholarly or scientific research; or a representative of the news media; and"],[1,"(III) for any request not described in (I) or (II), fees shall be limited to reasonable standard charges for document search and duplication."],[0,"In this clause, the term \"a representative of the news media\" means any person or entity that gathers information of potential interest to a segment of the public, uses its editorial skills to turn the raw materials into a distinct work, and distributes that work to an audience. In this clause, the term \"news\" means information that is about current events or that would be of current interest to the public. Examples of news-media entities are television or radio stations broadcasting to the public at large and publishers of periodicals (but only if such entities qualify as disseminators of \"news\") who make their products available for purchase by or subscription by or free distribution to the general public. These examples are not all-inclusive. Moreover, as methods of news delivery evolve (for example, the adoption of the electronic dissemination of newspapers through telecommunications services), such alternative media shall be considered to be news-media entities. A freelance journalist shall be regarded as working for a news-media entity if the journalist can demonstrate a solid basis for expecting publication through that entity, whether or not the journalist is actually employed by the entity. A publication contract would present a solid basis for such an expectation; the Government may also consider the past publication record of the requester in making such a determination."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/552?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§552. Public information; agency rules, opinions, orders, records, and proceedings","tname":"Government Organization and Employees","by":{"0":"17, 2, 34, 31, 7, 2, 7, 22, 34, 19","1":"1, 1, 32, 2, 10, 21, 23, 23, 23, 23","2":"22, 60, 5, 17, 23, passim, 40, 40","3":"20, 13, passim, 10, 14, 10"}},{"t":"usc","label":"7 U.S.C. § 2011","url":"https://www.law.cornell.edu/uscode/text/7/2011","stext":{"head":"§2011. Congressional declaration of policy","paras":[[0,"It is declared to be the policy of Congress, in order to promote the general welfare, to safeguard the health and well-being of the Nation's population by raising levels of nutrition among low-income households. Congress finds that the limited food purchasing power of low-income households contributes to hunger and malnutrition among members of such households. Congress further finds that increased utilization of food in establishing and maintaining adequate national levels of nutrition will promote the distribution in a beneficial manner of the Nation's agricultural abundance and will strengthen the Nation's agricultural economy, as well as result in more orderly marketing and distribution of foods. To alleviate such hunger and malnutrition, a supplemental nutrition assistance program is herein authorized which will permit low-income households to obtain a more nutritious diet through normal channels of trade by increasing food purchasing power for all eligible households who apply for participation."],[0,"That program includes as a purpose to assist low-income adults in obtaining employment and increasing their earnings. Such employment and earnings, along with program benefits, will permit low-income households to obtain a more nutritious diet through normal channels of trade by increasing food purchasing power for all eligible households who apply for participation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/2011?type=usc&year=mostrecent&link-type=html"},"head":"§2011. Congressional declaration of policy","tname":"Agriculture","by":{"0":"4","1":"2, 2, 2"}},{"t":"usc","label":"7 U.S.C. § 2018","url":"https://www.law.cornell.edu/uscode/text/7/2018","subs":["(c)","(a)(2)(A)","(a)(3)","(c)(1994)","(c)(2012)"],"stext":{"head":"§2018. Approval of retail food stores and wholesale food concerns","paras":[[0,"(a) Authorization to accept and redeem benefits"],[0,"(1) Applications.—"],[1,"(A) In general.—Regulations issued pursuant to this chapter shall provide for the submission of applications for approval by retail food stores and wholesale food concerns which desire to be authorized to accept and redeem benefits under the supplemental nutrition assistance program and for the approval of those applicants whose participation will effectuate the purposes of the supplemental nutrition assistance program."],[1,"(B) Factors for consideration.—In determining the qualifications of applicants, there shall be considered among such other factors as may be appropriate, the following:"],[2,"(i) the nature and extent of the food business conducted by the applicant;"],[2,"(ii) the volume of benefit transactions which may reasonably be expected to be conducted by the applicant food store or wholesale food concern;"],[2,"(iii) whether the applicant is located in an area with significantly limited access to food;"],[2,"(iv) any information, if available, about the ability of the anticipated or existing electronic benefit transfer equipment and service provider of the applicant to provide sufficient information through the electronic benefit transfer system to minimize the risk of fraudulent transactions; and"],[2,"(v) the business integrity and reputation of the applicant."],[1,"(C) Certificate.—Approval of an applicant shall be evidenced by the issuance to such applicant of a nontransferable certificate of approval."],[1,"(D) Visit required.—No retail food store or wholesale food concern of a type determined by the Secretary, based on factors that include size, location, and type of items sold, shall be approved to be authorized or reauthorized for participation in the supplemental nutrition assistance program unless an authorized employee of the Department of Agriculture, a designee of the Secretary, or, if practicable, an official of the State or local government designated by the Secretary has visited the store or concern for the purpose of determining whether the store or concern should be approved or reauthorized, as appropriate."],[0,"(2) The Secretary shall issue regulations providing for—"],[1,"(A) the periodic reauthorization of retail food stores and wholesale food concerns; and"],[1,"(B) periodic notice to participating retail food stores and wholesale food concerns of the definitions of \"retail food store\", \"staple foods\", \"eligible foods\", and \"perishable foods\"."],[0,"(3) Authorization periods.—The Secretary shall establish specific time periods during which authorization to accept and redeem benefits shall be valid under the supplemental nutrition assistance program."],[0,"(4) Electronic benefit transfer equipment and service providers.—Before implementing clause (iv) of paragraph (1)(B), the Secretary shall issue guidance for retail food stores on how to select electronic benefit transfer equipment and service providers that are able to meet the requirements of that clause."],[0,"(b) Effective and efficient operation of program; effect of disqualification; posting of bond"],[0,"(1) No wholesale food concern may be authorized to accept and redeem benefits unless the Secretary determines that its participation is required for the effective and efficient operation of the supplemental nutrition assistance program. No co-located wholesale-retail food concern may be authorized to accept and redeem benefits as a retail food store, unless (A) the concern does a substantial level of retail food business, or (B) the Secretary determines that failure to authorize such a food concern as a retail food store would cause hardship to households that receive supplemental nutrition assistance program benefits. In addition, no firm may be authorized to accept and redeem benefits as both a retail food store and as a wholesale food concern at the same time."],[0,"(2)(A) A buyer or transferee (other than a bona fide buyer or transferee) of a retail food store or wholesale food concern that has been disqualified under section 2021(a) of this title may not accept or redeem benefits until the Secretary receives full payment of any penalty imposed on such store or concern."],[0,"(B) A buyer or transferee may not, as a result of the sale or transfer of such store or concern, be required to furnish a bond under section 2021(d) of this title."],[0,"(c) Information submitted by applicants; safeguards; disclosure to and use by State agencies"],[0,"Regulations issued pursuant to this chapter shall require an applicant retail food store or wholesale food concern to submit information, which may include relevant income and sales tax filing documents, purchase invoices, records relating to electronic benefit transfer equipment and related services, transaction and redemption data provided through the electronic benefit transfer system, or program-related records, which will permit a determination to be made as to whether such applicant qualifies, or continues to qualify, for approval under the provisions of this chapter or the regulations issued pursuant to this chapter. The regulations may require retail food stores and wholesale food concerns to provide written authorization for the Secretary to verify all relevant tax filings with appropriate agencies and to obtain corroborating documentation from other sources so that the accuracy of information provided by the stores and concerns may be verified. Regulations issued pursuant to this chapter shall provide for safeguards which limit the use or disclosure of information obtained under the authority granted by this subsection to purposes directly connected with administration and enforcement of the provisions of this chapter or the regulations issued pursuant to this chapter, except that such information may be disclosed to and used by Federal law enforcement and investigative agencies and law enforcement and investigative agencies of a State government for the purposes of administering or enforcing this chapter or any other Federal or State law and the regulations issued under this chapter or such law, and State agencies that administer the special supplemental nutrition program for women, infants and children, authorized under section 17 of the Child Nutrition Act of 1966 [42 U.S.C. 1786], for purposes of administering the provisions of that Act [42 U.S.C. 1771 et seq.] and the regulations issued under that Act. Any person who publishes, divulges, discloses, or makes known in any manner or to any extent not authorized by Federal law (including a regulation) any information obtained under this subsection shall be fined not more than $1,000 or imprisoned not more than 1 year, or both. The regulations shall establish the criteria to be used by the Secretary to determine whether the information is needed. The regulations shall not prohibit the audit and examination of such information by the Comptroller General of the United States authorized by any other provision of law."],[0,"(d) Hearing upon failure of applicant to receive approval; waiting period for new application"],[0,"Any retail food store or wholesale food concern which has failed upon application to receive approval to participate in the supplemental nutrition assistance program may obtain a hearing on such refusal as provided in section 2023 of this title. A retail food store or wholesale food concern that is denied approval to accept and redeem benefits because the store or concern does not meet criteria for approval established by the Secretary may not, for at least 6 months, submit a new application to participate in the program. The Secretary may establish a longer time period under the preceding sentence, including permanent disqualification, that reflects the severity of the basis of the denial."],[0,"(e) Reporting of abuses by public"],[0,"Approved retail food stores shall display a sign providing information on how persons may report abuses they have observed in the operation of the supplemental nutrition assistance program."],[0,"(f) Limitation on participation of house-to-house trade routes"],[0,"In those areas in which the Secretary, in consultation with the Inspector General of the Department of Agriculture, finds evidence that the operation of house-to-house trade routes damages the program's integrity, the Secretary shall limit the participation of house-to-house trade routes to those routes that are reasonably necessary to provide adequate access to households."],[0,"(g) EBT service requirement"],[0,"An approved retail food store shall provide adequate EBT service as described in section 2016(h)(3)(B) of this title."],[0,"(h) Private establishments"],[0,"(1) In general"],[1,"Subject to paragraph (2), no private establishment that contracts with a State agency to offer meals at concessional prices as described in paragraphs (3), (4), and (9) of section 2012(k) of this title may be authorized to accept and redeem benefits unless the Secretary determines that the participation of the private establishment is required to meet a documented need in accordance with section 2020(e)(25) of this title."],[0,"(2) Existing contracts"],[0,"(A) In general"],[2,"If, on the day before February 7, 2014, a State has entered into a contract with a private establishment described in paragraph (1) and the Secretary has not determined that the participation of the private establishment is necessary to meet a documented need in accordance with section 2020(e)(25) of this title, the Secretary shall allow the operation of the private establishment to continue without that determination of need for a period not to exceed 180 days from the date on which the Secretary establishes determination criteria, by regulation, under section 2020(e)(25) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/2018?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2018. Approval of retail food stores and wholesale food concerns","tname":"Agriculture","by":{"0":"5, 7","1":"2, 2, 5, 5, 4, 4","2":"passim","3":"5, 6, 8"}},{"t":"usc","label":"15 U.S.C. § 4019","url":"https://www.law.cornell.edu/uscode/text/15/4019","by":{"0":"36"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 5413","url":"https://www.law.cornell.edu/uscode/text/42/5413","by":{"0":"36"}},{"t":"reg","label":"7 C.F.R. § 278.1","url":"https://www.ecfr.gov/current/title-7/section-278.1","subs":["(q)"],"by":{"0":"46"}},{"t":"reg","label":"43 Fed. Reg. 43,272","url":"https://www.govinfo.gov/link/fr/43/43272","by":{"0":"6"}},{"t":"reg","label":"79 Fed. Reg. 45,157","url":"https://www.govinfo.gov/link/fr/79/45157","by":{"0":"46"}},{"t":"case","label":"ASARCO Inc. v. Kadish","cite":"490 U.S. 605","y":1989,"id":"1988/87-1661","sc":1,"sum":"The judgment is affirmed. 155 Ariz. 484, 747 P. 2d 1183, affirmed. JUSTICE KENNEDY delivered the opinion of the Court with respect to Parts I, II-A, II-B-2, II-C, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Bender v. Williamsport Area Sch. Dist.","cite":"475 U.S. 534","y":1986,"id":"1985/84-773","sc":1,"sum":"Respondent had no standing to appeal, and therefore the Court of Appeals had no jurisdiction to hear his appeal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"(III) Cases—Continued: Brock v. Pierce Cnty.","cite":"476 U.S. 253","y":1986,"id":"1985/85-385","sc":1,"sum":"The Secretary does not lose the power to recover misused CETA funds after expiration of the 120-day period specified in § 106(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"op":4,"ar":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"1":"22","3":"8"}},{"t":"case","label":"CIA v. Sims","cite":"471 U.S. 159","y":1985,"id":"1984/83-1075","sc":1,"op":1,"ar":1,"sum":"Between 1953 and 1966, the Central Intelligence Agency (CIA) financed a research project, code-named MKULTRA, that was established to counter Soviet and Chinese advances in brainwashing and interrogation techniques. Subprojects were contracted out to various universities, research foundations, and similar institutions. In 1977, respondents in No. 83-1075 (hereafter respondents) filed a request with the CIA under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Critical Mass Energy Project v. Nuclear Regulatory Comm’n","cite":"975 F.2d 871","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/975/871/","op":2,"sum":"Describing “would customarily not be released to the public” as an “objective” test.","sumSrc":"brief:3","by":{"1":"20","2":"40, 41","3":"13, 17"}},{"t":"case","label":"Diamond v. Charles","cite":"476 U.S. 54","y":1986,"id":"1985/84-1379","sc":1,"sum":"Because appellant lacks any judicially cognizable interest in the Illinois Abortion Law, his appeal is dismissed for want of jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 33"}},{"t":"case","label":"Donaldson v. United States","cite":"400 U.S. 517","y":1971,"id":"1970/65","sc":1,"sum":"In furtherance of an investigation of petitioner's tax returns, respondent Grady, an Internal Revenue Service (IRS) Special Agent, issued summonses to petitioner's putative former employer (Acme) and its accountant for the production of Acme's records of petitioner's employment and compensation during the years under investigation. The summonses were issued under § 7602 of the Internal Revenue Code of 1954, which …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"FTC v. Grolier Inc.","cite":"462 U.S. 19","y":1983,"id":"1982/82-372","sc":1,"sum":"Under Exemption 5, attorney work product is exempt from mandatory disclosure without regard to the status of the litigation for which it was prepared. By its own terms, Exemption 5 requires reference to whether discovery would normally be required during litigation with the agency. Under a literal reading of Federal Rule of Civil Procedure 26(b)(3), the work product of agency attorneys would not be subject to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24","2":"33"}},{"t":"case","label":"Federal Open Mkt. Comm. of the Fed. Reserve Sys. v. Merrill","cite":"443 U.S. 340","y":1979,"id":"1978/77-1387","sc":1,"sum":"This case presents the question whether the Freedom of Information Act (FOIA) is violated by petitioner's practice, authorized by regulation, 12 CFR § 271.5 (1978), of withholding certain monetary policy directives from the public during the month they are in effect, such directives being published in full in the Federal Register at the end of the month. To implement its authority to conduct open market operations …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15","2":"50","3":"14, 15"}},{"t":"case","label":"Forsham v. Harris","cite":"445 U.S. 169","y":1980,"id":"1979/78-1118","sc":1,"sum":"HEW need not produce the requested data because they are not \"agency records\" within the meaning of the FOIA. Data generated by a privately controlled organization which has received federal grants (grantee), but which data has not at any time been obtained by the agency, are not \"agency records\" accessible under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10, 14"}},{"t":"case","label":"GTE Sylvania, Inc. v. Consumers Union of the U.S., Inc.","cite":"445 U.S. 375","y":1980,"id":"1979/78-1248","sc":1,"sum":"In connection with an investigation of hazards in the operation of television receivers, respondent Consumer Product Safety Commission (CPSC) obtained various accident reports from television manufacturers, including petitioners. Respondents Consumers Union of the United States, Inc., and Public Citizen's Health Research Group (requesters) sought disclosure of the accident reports under the Freedom of Information …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Grumman Aircraft Eng’g Corp. v. Renegotiation Bd.","cite":"425 F.2d 578","y":1970,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/425/578/","op":1,"by":{"1":"18"}},{"t":"case","label":"John Doe Agency v. John Doe Corp.","cite":"493 U.S. 146","y":1989,"id":"1989/88-1083","sc":1,"sum":"Exemption 7 may be invoked to prevent the disclosure of documents not originally created for, but later gathered for, law enforcement purposes. The plain words of the statute contain no requirement that compilation be effected at a specific time, but merely require that the objects sought be compiled when the Government invokes the Exemption. The Court of Appeals erred in interpreting the word \"compile\" to mean …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Lewis v. City of Chicago","cite":"560 U.S. 205","y":2010,"id":"2009/08-974","sc":1,"sum":"The Court held that an employee may file a Title VII disparate impact claim within 300 days after their employer executes the allegedly unlawful practice.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Riegel v. Medtronic, Inc.","cite":"552 U.S. 312","y":2008,"id":"2007/06-179","sc":1,"sum":"The Court, in an 8-1 decision, affirmed the Second Circuit and granted summary judgment in favor of Medtronic. The Court's opinion, written by Justice Antonin Scalia, noted that the MDA pre-empted state common law claims for defective devices such as this one.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"SEC v. Prudential Sec. Inc.","cite":"136 F.3d 153","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/136/153/","by":{"1":"33"}},{"t":"case","label":"Sandifer v. United States Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Texas Retailers Ass’n v. USDA","cite":"2019 WL 548966","y":2019,"court":"5th Cir. Feb. 11","by":{"1":"34"}},{"t":"case","label":"Town of Chester v. Laroe Estates, Inc.","cite":"137 S. Ct. 1645","y":2017,"id":"2016/16-605","sc":1,"sum":"The Court determined that an intervenor to a lawsuit must meet the requirements of Article III standing if the intervenor wishes to pursue relief that was not already requested by the plaintiff.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"United States v. Woods","cite":"571 U.S. 31","y":2013,"id":"2013/12-562","sc":1,"sum":"The Court held that, under the Tax Equity and Fiscal Responsibility Act of 1982, a court in partnership-level proceedings has the right to consider the applicability of any penalty that relates to the partnership.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"12, 31, 34","2":"1, 8, 13, 14"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(2)"],"by":{"1":"1, 9"}},{"t":"law","label":"Pub. L. No. 109-282","url":"https://www.govinfo.gov/link/plaw/109/public/282","by":{"1":"25"}},{"t":"usc","label":"7 U.S.C. § 2013","url":"https://www.law.cornell.edu/uscode/text/7/2013","subs":["(a)(2012)","(a)"],"stext":{"head":"§2013. Establishment of supplemental nutrition assistance program","paras":[[0,"(a) In general"],[0,"Subject to the availability of funds appropriated under section 2027 of this title, the Secretary is authorized to formulate and administer a supplemental nutrition assistance program under which, at the request of the State agency, eligible households within the State shall be provided an opportunity to obtain a more nutritious diet through the issuance to them of an allotment, except that a State may not participate in the supplemental nutrition assistance program if the Secretary determines that State or local sales taxes are collected within that State on purchases of food made with benefits issued under this chapter. The benefits so received by such households shall be used only to purchase food from retail food stores which have been approved for participation in the supplemental nutrition assistance program. Benefits issued and used as provided in this chapter shall be redeemable at face value by the Secretary through the facilities of the Treasury of the United States."],[0,"(b) Food distribution program on Indian reservations"],[0,"(1) In general"],[1,"Distribution of commodities, with or without the supplemental nutrition assistance program, shall be made whenever a request for concurrent or separate food program operations, respectively, is made by a tribal organization."],[0,"(2) Administration"],[0,"(A) In general"],[2,"Subject to subparagraphs (B) and (C), in the event of distribution on all or part of an Indian reservation, the appropriate agency of the State government in the area involved shall be responsible for the distribution."],[0,"(B) Administration by tribal organization"],[2,"If the Secretary determines that a tribal organization is capable of effectively and efficiently administering a distribution described in paragraph (1), then the tribal organization shall administer the distribution."],[0,"(C) Prohibition"],[2,"The Secretary shall not approve any plan for a distribution described in paragraph (1) that permits any household on any Indian reservation to participate simultaneously in the supplemental nutrition assistance program and the program established under this subsection."],[0,"(3) Disqualified participants"],[1,"An individual who is disqualified from participation in the food distribution program on Indian reservations under this subsection is not eligible to participate in the supplemental nutrition assistance program under this chapter for a period of time to be determined by the Secretary."],[0,"(4) Administrative costs"],[0,"(A) In general"],[2,"Subject to subparagraph (B), the Secretary shall pay not less than 80 percent of administrative costs and distribution costs on Indian reservations as the Secretary determines necessary for effective administration of such distribution by a State agency or tribal organization."],[0,"(B) Waiver"],[2,"The Secretary shall waive up to 100 percent of the non-Federal share of the costs described in subparagraph (A) if the Secretary determines that—"],[3,"(i) the tribal organization is financially unable to provide a greater non-Federal share of the costs; or"],[3,"(ii) providing a greater non-Federal share of the costs would be a substantial burden for the tribal organization."],[0,"(C) Limitation"],[2,"The Secretary may not reduce any benefits or services under the food distribution program on Indian reservations under this subsection to any tribal organization that is granted a waiver under subparagraph (B)."],[0,"(D) Tribal contribution"],[2,"The Secretary may allow a tribal organization to use funds provided to the tribal organization through a Federal agency or other Federal benefit to satisfy all or part of the non-Federal share of the costs described in subparagraph (A) if that use is otherwise consistent with the purpose of the funds."],[0,"(5) Bison meat"],[1,"Subject to the availability of appropriations to carry out this paragraph, the Secretary may purchase bison meat for recipients of food distributed under this subsection, including bison meat from—"],[2,"(A) Native American bison producers; and"],[2,"(B) producer-owned cooperatives of bison ranchers."],[0,"(6) Traditional and locally- and regionally-grown food fund"],[0,"(A) In general"],[2,"Subject to the availability of appropriations, the Secretary shall establish a fund for use in purchasing traditional and locally- and regionally-grown foods for recipients of food distributed under this subsection."],[0,"(B) Native American producers"],[2,"Where practicable, of the food provided under subparagraph (A), at least 50 percent shall be produced by Native American farmers, ranchers, and producers."],[0,"(C) Definition of traditional and locally- and regionally-grown"],[2,"The Secretary shall determine the definition of the term \"traditional and locally- and regionally-grown\" with respect to food distributed under this paragraph."],[0,"(D) Purchase of foods"],[2,"In carrying out this paragraph, the Secretary shall purchase or offer to purchase those traditional foods that may be procured cost-effectively."],[0,"(E) Authorization of appropriations"],[2,"There is authorized to be appropriated to the Secretary to carry out this paragraph $5,000,000 for each of fiscal years 2008 through 2023."],[0,"(7) Availability of funds"],[0,"(A) In general"],[2,"Funds made available for a fiscal year to carry out this subsection shall remain available for obligation for a period of 2 fiscal years."],[0,"(B) Administrative costs"],[2,"Funds made available for a fiscal year to carry out paragraph (4) shall remain available for obligation by the State agency or tribal organization for a period of 2 fiscal years."],[0,"(c) Regulations; transmittal of copy of regulations to Congressional committees prior to issuance"],[0,"The Secretary shall issue such regulations consistent with this chapter as the Secretary deems necessary or appropriate for the effective and efficient administration of the supplemental nutrition assistance program and shall promulgate all such regulations in accordance with the procedures set forth in section 553 of title 5. In addition, prior to issuing any regulation, the Secretary shall provide the Committee on Agriculture of the House of Representatives and the Committee on Agriculture, Nutrition, and Forestry of the Senate a copy of the regulation with a detailed statement justifying it."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/2013?type=usc&year=mostrecent&link-type=html"},"head":"§2013. Establishment of supplemental nutrition assistance program","tname":"Agriculture","by":{"1":"2","3":"20"}},{"t":"usc","label":"7 U.S.C. § 2016","url":"https://www.law.cornell.edu/uscode/text/7/2016","subs":["(a)","(b)","(h)(1)"],"by":{"1":"2, 2, 3, 2"}},{"t":"usc","label":"7 U.S.C. § 2019","url":"https://www.law.cornell.edu/uscode/text/7/2019","subs":["(2012)"],"stext":{"head":"§2019. Redemption of program benefits","paras":[[0,"Regulations issued pursuant to this chapter shall provide for the redemption of benefits accepted by retail food stores through approved wholesale food concerns or through financial institutions which are insured by the Federal Deposit Insurance Corporation, or which are insured under the Federal Credit Union Act [12 U.S.C. 1751 et seq.] and have retail food stores or wholesale food concerns in their field of membership, with the cooperation of the Treasury Department, except that retail food stores defined in section 2012(o)(4) of this title shall be authorized to redeem their members' food benefits prior to receipt by the members of the food so purchased, retail food stores authorized to accept and redeem benefits through on-line transactions shall be authorized to accept benefits prior to the delivery of food if the delivery occurs within a reasonable time of the purchase, as determined by the Secretary, and publicly operated community mental health centers or private nonprofit organizations or institutions which serve meals to narcotics addicts or alcoholics in drug addiction or alcoholic treatment and rehabilitation programs, public and private nonprofit shelters that prepare and serve meals for battered women and children, and public or private nonprofit group living arrangements that serve meals to disabled or blind residents, shall not be authorized to redeem benefits through financial institutions which are insured by the Federal Deposit Insurance Corporation or the Federal Credit Union Act. Notwithstanding the preceding sentence, a center, organization, institution, shelter, group living arrangement, or establishment described in that sentence may be authorized to redeem benefits through a financial institution described in that sentence if the center, organization, institution, shelter, group living arrangement, or establishment is equipped with 1 or more point-of-sale devices and is operating in an area in which an electronic benefit transfer system described in section 2016(h) of this title has been implemented. No financial institution may impose on or collect from a retail food store a fee or other charge for the redemption of benefits that are submitted to the financial institution in a manner consistent with the requirements, other than any requirements relating to cancellation of benefits, for the presentation of benefits by financial institutions to the Federal Reserve banks."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/2019?type=usc&year=mostrecent&link-type=html"},"head":"§2019. Redemption of program benefits","tname":"Agriculture","by":{"1":"4","2":"21"}},{"t":"usc","label":"7 U.S.C. § 2020","url":"https://www.law.cornell.edu/uscode/text/7/2020","subs":["(a)(1)"],"by":{"1":"2"}},{"t":"law","label":"Pub. L. No. 110-246","url":"https://www.govinfo.gov/link/plaw/110/public/246","by":{"1":"2"}},{"t":"law","label":"Pub. L. No. 99-198","url":"https://www.govinfo.gov/link/statute/99/1579","by":{"1":"28"}},{"t":"law","label":"Pub. L. No. 103-225","url":"https://www.govinfo.gov/link/statute/108/108","by":{"1":"29"}},{"t":"reg","label":"3 C.F.R. pt. 235","url":"https://www.ecfr.gov/current/title-3/part-235","by":{"1":"23, 23, 23"}},{"t":"reg","label":"3 C.F.R. pt. 236","url":"https://www.ecfr.gov/current/title-3/part-236","by":{"1":"23, 23"}},{"t":"reg","label":"3 C.F.R. pt. 237","url":"https://www.ecfr.gov/current/title-3/part-237","by":{"1":"23"}},{"t":"reg","label":"48 C.F.R. § 4.603","url":"https://www.ecfr.gov/current/title-48/section-4.603","subs":["(a)"],"by":{"1":"25"}},{"t":"reg","label":"51 Fed. Reg. 43,612","url":"https://www.govinfo.gov/link/fr/51/43612","by":{"1":"28"}},{"t":"reg","label":"60 Fed. Reg. 25,625","url":"https://www.govinfo.gov/link/fr/60/25625","by":{"1":"29"}},{"t":"reg","label":"64 Fed. Reg. 17,604","url":"https://www.govinfo.gov/link/fr/64/17604","by":{"1":"29"}},{"t":"reg","label":"75 Fed. Reg. 81,205","url":"https://www.govinfo.gov/link/fr/75/81205","by":{"1":"29"}},{"t":"case","label":"Acumenics Research & Tech. v. Dep’t of Justice","cite":"843 F.2d 800","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/843/800/","by":{"2":"25, 58"}},{"t":"case","label":"Adarand Constructors, Inc. v. Mineta","cite":"534 U.S. 103","y":2001,"id":"2001/00-730","sc":1,"sum":"After Adarand asserted that it was only challenging the rules pertaining to the direct procurement of DOT funds for highway construction on federal lands rather than any part of the DOT's DBE program as it pertained to state and local procurement, the Court concluded that the posture of the case had changed.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Alpha Distrib. Co. of Cal., Inc. v. Jack Daniel’s Distillery","cite":"207 F. Supp. 136","y":1961,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./207/136/","by":{"2":"31"}},{"t":"case","label":"Apple Inc. v. Samsung Elecs. Co.","cite":"727 F.3d 1214","y":2013,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/727/1214/","by":{"2":"50"}},{"t":"case","label":"Aronson v. Quick Point Pencil Co.","cite":"440 U.S. 257","y":1979,"id":"1978/77-1413","sc":1,"sum":"Federal patent law does not pre-empt state contract law so as to preclude enforcement of the contract. Cf. Kewanee Oil Co. v. Bicron Corp., 416 U. S. 470.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32"}},{"t":"case","label":"Bloomberg, L.P. v. Bd. of Governors of the Fed. Reserve Sys.","cite":"601 F.3d 143","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/601/143/","sum":"Holding information about Federal Reserve loans was not “obtained from” the private loan applicants because they were records of “the agency’s own executive actions”.","sumSrc":"brief:2","by":{"2":"65","3":"19"}},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"sum":"The Court found that the IRS was correct in its decision to revoke the tax-exempt status of Bob Jones University and the Goldsboro Christian School. These institutions did not meet the requirement by providing \"beneficial and stabilizing influences in community life\" to be supported by taxpayers with a special tax status. The schools could not meet this requirement due to their discriminatory policies.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Canadian Commercial Corp. v. Dep’t of Air Force","cite":"514 F.3d 37","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/514/37/","by":{"2":"15, 16"}},{"t":"case","label":"Carpenter v. United States","cite":"484 U.S. 19","y":1987,"id":"1987/86-422","sc":1,"sum":"The Court held that pre-release of a newspaper’s publication schedule qualifies as using mail and wire as an essential part of a scheme to defraud an entity of their property.","sumSrc":"Oyez","by":{"2":"35","3":"12, 14"}},{"t":"case","label":"Cause of Action v. F.T.C.","cite":"799 F.3d 1108","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/799/1108/","by":{"2":"60"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Clear Channel Commc’ns, Inc. v. United Servs. Auto. Ass’n","cite":"195 S.W.3d 129","y":2006,"court":"Tex. Ct. App.","url":"https://www.courtlistener.com/c/S.W.3d/195/129/","by":{"2":"50"}},{"t":"case","label":"Cmty. for Creative Non-Violence v. Reid","cite":"490 U.S. 730","y":1989,"id":"1988/88-293","sc":1,"sum":"The Court held that the statue's preparation was not a \"work for hire\" as defined by the Act because Reid was not a CCNV employee. Instead, CCNV hired Reid as an independent contractor.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Contract Freighters, Inc. v. Dep’t of Transp.","cite":"260 F.3d 858","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/260/858/","op":1,"by":{"2":"25"}},{"t":"case","label":"Corning Glass Works v. U.S. Int’l Trade Comm’n","cite":"799 F.2d 1559","y":1986,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/799/1559/","by":{"2":"46"}},{"t":"case","label":"Davis v. United States","cite":"495 U.S. 472","y":1990,"id":"1989/89-98","sc":1,"sum":"Section 170 of the Internal Revenue Code of 1954 permits a taxpayer to claim a charitable contribution deduction only if the contribution is made \"to or for the use of\" a qualified organization. Petitioner husband and wife, who are members of the Church of Jesus Christ of Latter-day Saints (Church) claimed such deductions for funds transferred to their sons while they were serving as full-time, unpaid missionaries …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"Dep’t of Air Force v. Rose","cite":"425 U.S. 352","y":1976,"id":"1975/74-489","sc":1,"op":1,"sum":"Under the United States Air Force Academy's Honor Code, which is administered by a cadet committee, cadets pledge that they will not lie, steal, or cheat, or tolerate among their number anyone who does. If a cadet investigatory team finds that a hearing before an Honor Board concerning a suspected violation is warranted, the accused may call witnesses, and cadet observers attend. The Board, consisting of eight …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"Det. Watch Network v. Corr. Corp. of Am.","cite":"2017 WL 4122728","y":2017,"court":"Feb. 8","by":{"2":"16","3":"5"}},{"t":"case","label":"Doe v. Doe, ___ S.E.2d ___","cite":"2018 WL 6613818","y":2018,"court":"N.C. Ct. App. Dec. 18","by":{"2":"50"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"sum":"After respondent Mans filed for relief under Chapter 11 of the Bankruptcy Code, petitioners William and Norinne Field alleged, in effect, that letters Mans had written to them constituted fraudulent representations on which they relied in continuing to extend credit to a corporation controlled by Mans, and that, accordingly, Mans's obligation to them as guarantor of the corporation's debt should be excepted from …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32"}},{"t":"case","label":"Flood v. Kuhn","cite":"407 U.S. 258","y":1972,"id":"1971/71-32","sc":1,"sum":"He also cited Toolson , where the Court specifically held that the business of holding public baseball games for profit between professional clubs was not within the scope of federal antitrust laws. Justice Blackmun also noted that Federal Baseball and Toolson were frequently and favorably cited in other cases to establish the uniqueness of baseball’s exemption.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Food Processes, Inc. v. Swift & Co.","cite":"280 F. Supp. 353","y":1966,"court":"W.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp./280/353/","by":{"2":"31"}},{"t":"case","label":"Fox News Network, LLC v. Bd. of Governors of the Fed. Reserve Sys.","cite":"601 F.3d 158","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/601/158/","by":{"2":"55"}},{"t":"case","label":"Haig v. Agee","cite":"453 U.S. 280","y":1981,"id":"1980/80-83","sc":1,"sum":"In a 7-to-2 decision, the Court held that Passport Act of 1926 and other congressional statutes implicitly granted the Secretary of State the power to revoke passports.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Hall v. Hall","cite":"138 S. Ct. 1118","y":2018,"id":"2017/16-1150","sc":1,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"2":"28","3":"9"}},{"t":"case","label":"Helsinn Healthcare S.A. v. Teva Pharm. USA, Inc.","cite":"139 S. Ct. 628","y":2019,"id":"2018/17-1229","sc":1,"op":1,"ar":5,"sum":"The sale of an invention to a third party who is obligated to keep the invention confidential may place the invention “on sale” for purposes of the Leahy-Smith America Invents Act, which bars a person from receiving a patent on an invention that was “in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention,” 35 U. S. C. §102(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"37, 63","3":"16"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Jaffee v. Redmond","cite":"518 U.S. 1","y":1996,"id":"1995/95-266","sc":1,"sum":"Announced by Justice John Paul Stevens, the Court ruled that Federal Rule of Evidence 501 protects the conversations between Redmond and her therapist from compelled disclosure. The Rule recognizes a \"psychotherapist-patient privilege.\".","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Judicial Watch, Inc. v. FDA","cite":"449 F.3d 141","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/449/141/","by":{"2":"56"}},{"t":"case","label":"King v. Bryant","cite":"795 S.E.2d 340","y":2017,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E.2d/795/340/","by":{"2":"46"}},{"t":"case","label":"Lawson v. FMR LLC","cite":"571 U.S. 429","y":2014,"id":"2013/12-3","sc":1,"sum":"The Court held that the whistleblower-protection section of the Sarbanes-Oxley Act applies to privately-employed individuals.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Leucadia, Inc. v. Applied Extrusion Techs., Inc.","cite":"998 F.2d 157","y":1993,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/998/157/","by":{"2":"49"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"ar":5,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"2":"38","3":"16"}},{"t":"case","label":"Lujan v. Defs. of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"2":"14, 15, 16"}},{"t":"case","label":"Lyon v. Gen. Motors Corp.","cite":"200 F. Supp. 89","y":1961,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./200/89/","by":{"2":"31"}},{"t":"case","label":"Manhattan Props., Inc. v. Irving Tr. Co.","cite":"291 U.S. 320","y":1934,"id":"scdb/1933-048","sc":1,"sum":"1. The claim of a landlord for future rents based on a covenant to p'ay rent in a lease terminated by reintry on the bankruptcy of the tenant, is not a provable debt under § 63 (a) of the Bankruptcy Act. P. 332. So held in view of the great weight of judicial authority construing that section and similar provisions of earlier Acts, and in view of the legislative history of the subject.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40"}},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"sum":"The Court held that a conviction under 26 U.S.C. § 7212(a) for corruptly endeavoring to obstruct or impede the due administration of the tax laws requires proof that the defendant acted with knowledge of a pending Internal Revenue Service action.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"2":"63"}},{"t":"case","label":"McBurney v. Young","cite":"569 U.S. 221","y":2013,"id":"2012/12-17","sc":1,"sum":"The Court found that under the Privileges and Immunities clause and the Dormant Commerce clause, a state can deny access to its public records to citizens of another state.","sumSrc":"Oyez","by":{"2":"53","3":"15"}},{"t":"case","label":"McDonald’s Corp. v. Moore","cite":"243 F. Supp. 255","y":1965,"court":"S.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./243/255/","by":{"2":"31"}},{"t":"case","label":"Metropolis Bending Co. v. Brandwen","cite":"8 F.R.D. 296","y":1948,"court":"M.D. Pa.","url":"https://www.courtlistener.com/c/F.R.D./8/296/","by":{"2":"31"}},{"t":"case","label":"Molzof v. United States","cite":"502 U.S. 301","y":1992,"id":"1991/90-838","sc":1,"sum":"The District Court awarded the guardian ad litem of petitioner Molzof's since-deceased husband damages under the Federal Tort Claims Act (FTCA or Act) for supplemental medical care for injuries suffered by Mr. Molzof as a result of the negligence of federal employees, but refused to award damages for future medical expenses and for loss of enjoyment of life. The Court of Appeals affirmed, ruling that damages of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Mosallem v. Berenson","cite":"76 A.D.3d 345","y":2010,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D.3d/76/345/","by":{"2":"50"}},{"t":"case","label":"Nat’l Council of La Raza v. Dep’t of Justice","cite":"411 F.3d 350","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/411/350/","by":{"2":"32"}},{"t":"case","label":"Nat’l Treasury Emps. Union v. Von Raab","cite":"489 U.S. 656","y":1989,"id":"1988/86-1879","sc":1,"sum":"The Court held that the \"substantial interests\" of the government in stifling the drug trade justified \"departure from the ordinary warrant and probable cause requirements\" associated with searches.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"2":"27, 28"}},{"t":"case","label":"New Jersey Bell Tel. Co. v. NLRB","cite":"720 F.2d 789","y":1983,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/720/789/","by":{"2":"46"}},{"t":"case","label":"Nixon v. Warner Commc’ns, Inc.","cite":"435 U.S. 589","y":1978,"id":"1977/76-944","sc":1,"sum":"During the criminal trial of several of petitioner ex-President's former advisers on charges, inter alia, of conspiring to obstruct justice in connection with the so-called Watergate investigation, some 22 hours of tape recordings made of conversations in petitioner's offices in the White House and Executive Office Building were played to the jury and the public in the courtroom, and the reels of the tapes were …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49, 53","3":"15"}},{"t":"case","label":"NLRB v. Robbins Tire & Rubber Co.","cite":"437 U.S. 214","y":1978,"id":"1977/77-911","sc":1,"sum":"The Court of Appeals erred in holding that the NLRB was not entitled to withhold the witness statements under Exemption 7 (A).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"PepsiCo, Inc. v. Redmond","cite":"54 F.3d 1262","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/54/1262/","by":{"2":"47"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) authorizes the Environmental Protection Agency (EPA) to use data submitted by an applicant for registration of a covered product (hereinafter pesticide) in evaluating the application of a subsequent applicant, and to disclose publicly some of the submitted data. Under the dataconsideration provisions of § 3, as amended in 1978, applicants now are …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16, 35, 62"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"SEC v. Lavin","cite":"111 F.3d 921","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/111/921/","by":{"2":"34"}},{"t":"case","label":"Seismograph Serv. Corp. v. Offshore Raydist, Inc.","cite":"135 F. Supp. 342","y":1955,"court":"E.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp./135/342/","by":{"2":"31"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Shapiro v. United States","cite":"335 U.S. 1","y":1948,"id":"scdb/1947-110","sc":1,"sum":"The plea in bar was properly overruled by the trial court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37, 38"}},{"t":"case","label":"Sharkey v. FDA","cite":"250 F. App’x 284","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/250/284/","by":{"2":"47"}},{"t":"case","label":"Smith v. Dravo Corp.","cite":"203 F.2d 369","y":1953,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/203/369/","by":{"2":"31"}},{"t":"case","label":"Sybron Corp. v. Wetzel","cite":"385 N.E.2d 1055","y":1978,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/385/1055/","by":{"2":"31"}},{"t":"case","label":"United States v. Wallington","cite":"889 F.2d 573","y":1989,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/889/573/","by":{"2":"16"}},{"t":"case","label":"USM Corp. v. Marson Fastener Corp.","cite":"393 N.E.2d 895","y":1979,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/393/895/","by":{"2":"31"}},{"t":"case","label":"Vantage Health Plan, Inc. v. WillisKnighton Med. Ctr.","cite":"913 F.3d 443","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/913/443/","by":{"2":"50"}},{"t":"case","label":"Zuber v. Allen","cite":"396 U.S. 168","y":1969,"id":"1969/25","sc":1,"sum":"Respondent Vermont dairy farmers (\"country\" milk producers) brought this action to invalidate the so-called farm location differential provided for by order of the Secretary of Agriculture as contrary to the Agricultural Marketing Agreement Act of 1937. The effect of the order is to require milk distributors to pay milk producers situated close to milk marketing areas (\"nearby\" farmers) higher prices than are paid …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"2":"53"}},{"t":"law","label":"Agriculture Improvement Act, Pub. L. No. 115-334","url":"https://www.govinfo.gov/link/plaw/115/public/334","by":{"2":"22"}},{"t":"law","label":"Freedom of Information Act Amendments, Pub. L. No. 93-502","url":"https://www.govinfo.gov/link/statute/88/1561","by":{"2":"40"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"2":"40"}},{"t":"law","label":"Pub. L. No. 110-175","url":"https://www.govinfo.gov/link/plaw/110/public/175","by":{"2":"39"}},{"t":"usc","label":"18 U.S.C. § 1905","url":"https://www.law.cornell.edu/uscode/text/18/1905","by":{"2":"15"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"by":{"2":"18"}},{"t":"usc","label":"5 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/5/1002","subs":["(c)(1964)"],"by":{"2":"60"}},{"t":"usc","label":"7 U.S.C. § 2619","url":"https://www.law.cornell.edu/uscode/text/7/2619","by":{"2":"48"}},{"t":"usc","label":"7 U.S.C. § 4912","url":"https://www.law.cornell.edu/uscode/text/7/4912","by":{"2":"48"}},{"t":"usc","label":"10 U.S.C. § 129d","url":"https://www.law.cornell.edu/uscode/text/10/129d","by":{"2":"48"}},{"t":"usc","label":"11 U.S.C. § 107","url":"https://www.law.cornell.edu/uscode/text/11/107","subs":["(b)(1)"],"stext":{"head":"§107. Public access to papers","paras":[[0,"(a) Except as provided in subsections (b) and (c) and subject to section 112, a paper filed in a case under this title and the dockets of a bankruptcy court are public records and open to examination by an entity at reasonable times without charge."],[0,"(b) On request of a party in interest, the bankruptcy court shall, and on the bankruptcy court's own motion, the bankruptcy court may—"],[1,"(1) protect an entity with respect to a trade secret or confidential research, development, or commercial information; or"],[1,"(2) protect a person with respect to scandalous or defamatory matter contained in a paper filed in a case under this title."],[0,"(c)(1) The bankruptcy court, for cause, may protect an individual, with respect to the following types of information to the extent the court finds that disclosure of such information would create undue risk of identity theft or other unlawful injury to the individual or the individual's property:"],[1,"(A) Any means of identification (as defined in section 1028(d) of title 18) contained in a paper filed, or to be filed, in a case under this title."],[1,"(B) Other information contained in a paper described in subparagraph (A)."],[0,"(2) Upon ex parte application demonstrating cause, the court shall provide access to information protected pursuant to paragraph (1) to an entity acting pursuant to the police or regulatory power of a domestic governmental unit."],[0,"(3) The United States trustee, bankruptcy administrator, trustee, and any auditor serving under section 586(f) of title 28—"],[1,"(A) shall have full access to all information contained in any paper filed or submitted in a case under this title; and"],[1,"(B) shall not disclose information specifically protected by the court under this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/107?type=usc&year=mostrecent&link-type=html"},"head":"§107. Public access to papers","tname":"Bankruptcy","by":{"2":"49","3":"15"}},{"t":"usc","label":"15 U.S.C. § 57b-2","url":"https://www.law.cornell.edu/uscode/text/15/57b-2","by":{"2":"48"}},{"t":"usc","label":"21 U.S.C. § 830","url":"https://www.law.cornell.edu/uscode/text/21/830","subs":["(c)(1)"],"by":{"2":"37"}},{"t":"usc","label":"31 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/31/3553","by":{"2":"48"}},{"t":"usc","label":"42 U.S.C. § 17244","url":"https://www.law.cornell.edu/uscode/text/42/17244","subs":["(h)"],"by":{"2":"39"}},{"t":"usc","label":"49 U.S.C. § 309","url":"https://www.law.cornell.edu/uscode/text/49/309","by":{"2":"37"}},{"t":"usc","label":"49 U.S.C. § 24322","url":"https://www.law.cornell.edu/uscode/text/49/24322","by":{"2":"48"}},{"t":"reg","label":"7 C.F.R. § 278.4","url":"https://www.ecfr.gov/current/title-7/section-278.4","subs":["(c)"],"by":{"2":"20"}},{"t":"reg","label":"28 C.F.R. § 16.7","url":"https://www.ecfr.gov/current/title-28/section-16.7","by":{"2":"58"}},{"t":"reg","label":"79 Fed. Reg. 45,175","url":"https://www.govinfo.gov/link/fr/79/45175","by":{"2":"6"}},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","subs":["(c)(1)(G)"],"by":{"2":"50, 51"}},{"t":"rule","label":"Fed. R. Civ. P. 45","url":"https://www.law.cornell.edu/rules/frcp/rule_45","subs":["(d)(3)(B)(i)"],"by":{"2":"48, 50, 51"}},{"t":"reg","label":"Exec. Order No. 11652, 37 Fed. Reg. 5209","url":"https://www.govinfo.gov/link/fr/37/5209","by":{"2":"48"}},{"t":"case","label":"100Reporters LLC v. U.S. Department of Justice","cite":"307 F.R.D. 269","y":2014,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.R.D./307/269/","by":{"3":"4"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Campbell-Ewald Co. v. Gomez","cite":"136 S. Ct. 663","y":2016,"id":"2015/14-857","sc":1,"sum":"The Court held that an unaccepted settlement offer does not make a plaintiff’s claim moot, and a federal contractor does not have derivative sovereign liability from a suit under the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2008,"id":"1999/99-5716","sc":1,"sum":"The Court held that federal bank larceny is not a \"lesser included offense\" of federal bank robbery. The \"[p]etitioner is accordingly prohibited as a matter of law from obtaining a lesser included offense instruction,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"3":"8, 11"}},{"t":"case","label":"Didrickson v. U.S. Department of the Interior","cite":"982 F.2d 1332","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/982/1332/","by":{"3":"5"}},{"t":"case","label":"Dow Jones & Co., Inc. v. U.S. Department of Justice","cite":"161 F.R.D. 247","y":1995,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.R.D./161/247/","by":{"3":"5"}},{"t":"case","label":"Friends of the Earth, Inc. v. Laidlaw Environmental Services (TOC), Inc.","cite":"528 U.S. 167","y":2000,"id":"1999/98-822","sc":1,"sum":"The Court held that a citizen suitor's claim for civil penalties need not be dismissed as moot when the defendant, after commencement of the litigation, has come into compliance with its NPDES permit. \"A defendant's voluntary cessation of allegedly unlawful conduct ordinarily does not suffice to moot a case,\" Justice Ginsburg wrote for the Court. \"Congress has found that civil penalties in the Clean Water Act cases do more than promote immediate compliance... they also deter future violations,\" concluded Justice Ginsburg.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Jones v. Liberty Glass Co.","cite":"332 U.S. 524","y":1947,"id":"scdb/1947-015","sc":1,"sum":"1. Under § 322 (b) (1) of the Internal Revenue Code, a claim for refund of federal income tax, whether arising out of an income tax \"erroneously or illegally assessed or collected\" or not, must be. filed within three years from the time the return was filed or within two years from the time the tax was paid. The four-year period prescribed by § 3313 is inapplicable to such a claim. Pp. 525-526, 534-535.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Monsanto Co. v. Geertson Seed Farms","cite":"561 U.S. 139","y":2010,"id":"2009/09-475","sc":1,"op":2,"sum":"The Court held that a district court must conduct an evidentiary hearing to enter an injunction.","sumSrc":"Oyez","by":{"3":"6, 7"}},{"t":"case","label":"NLRB v. Bildisco & Bildisco","cite":"465 U.S. 513","y":1984,"id":"1983/82-818","sc":1,"op":1,"sum":"Section 365(a) of the Bankruptcy Code (Code) provides that, with certain exceptions, the trustee, subject to the Bankruptcy Court's approval, may assume or reject \"any executory contract\" of the debtor. In April 1980, respondent debtor (hereafter respondent), a building supplies distributor, filed a voluntary petition in bankruptcy for reorganization under Chapter 11 of the Code, and was subsequently authorized by …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"SAS Institute, Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"sum":"Authored by Justice David H. Souter, the Court ruled that the materiality of falsehood is not an element of the crime of knowingly making a false statement to a federally insured bank. Justice Souter wrote for the court that prosecutors need not prove that a lie was relevant enough to affect the outcome of a bank's decision because the law does not require such materiality.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"Washington Post Co. v. U.S. Department of Health & Human Services","cite":"865 F.2d 320","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/865/320/","by":{"3":"20"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"3":"5"}}]};